package com.veer.maya;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.speech.*;import android.speech.tts.*;import java.util.*;
public class MayaVoiceService extends Service{static MayaVoiceService me;SpeechRecognizer sr;TextToSpeech tts;public static void start(Context c){Intent i=new Intent(c,MayaVoiceService.class);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);}public static void stop(Context c){c.stopService(new Intent(c,MayaVoiceService.class));}public static void say(String s){if(me!=null&&me.tts!=null)me.tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"maya");}
public void onCreate(){super.onCreate();me=this;NotificationChannel ch=new NotificationChannel("maya","MAYA Voice",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(ch);Notification n=new Notification.Builder(this,"maya").setContentTitle("MAYA listening").setContentText("Voice assistant active").setSmallIcon(android.R.drawable.ic_btn_speak_now).setOngoing(true).build();if(Build.VERSION.SDK_INT>=29)startForeground(7,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE);else startForeground(7,n);tts=new TextToSpeech(this,x->tts.setLanguage(Locale.getDefault()));listen();}
void listen(){if(sr!=null)try{sr.destroy();}catch(Exception e){}if(checkSelfPermission("android.permission.RECORD_AUDIO")!=PackageManager.PERMISSION_GRANTED)return;sr=SpeechRecognizer.createSpeechRecognizer(this);sr.setRecognitionListener(new RecognitionListener(){public void onResults(Bundle b){ArrayList<String>a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a!=null&&!a.isEmpty()){String x=a.get(0);String l=x.toLowerCase(Locale.US);if(l.contains("maya")||x.contains("माया")){x=x.replaceAll("(?i)\bmaya\b","").replace("माया","").trim();if(x.isEmpty())say("हाँ, बोलिए");else MayaCore.process(MayaVoiceService.this,x);}}new Handler().postDelayed(()->listen(),600);}public void onError(int e){new Handler().postDelayed(()->listen(),800);}public void onReadyForSpeech(Bundle b){}public void onBeginningOfSpeech(){}public void onRmsChanged(float r){}public void onBufferReceived(byte[]b){}public void onEndOfSpeech(){}public void onPartialResults(Bundle b){}public void onEvent(int a,Bundle b){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);sr.startListening(i);}
public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public void onDestroy(){try{sr.destroy();}catch(Exception e){}if(tts!=null)tts.shutdown();me=null;super.onDestroy();}public IBinder onBind(Intent i){return null;}}